public Mono<PageDto<User>> findPage(Pageable pageable) {
    Flux<User> data = template.select(User.class)
        .matching(query(empty()).with(pageable))
        .all();
    Mono<Long> total = template.select(User.class)
        .matching(query(empty()))
        .count();
    return data.collectList()
        .zipWith(total)
        .map(t -> new PageDto<>(t.getT1(), t.getT2(), pageable));
}
